#### Phase 2: Core Implementation (Week 2-3)

**Step 2.1: Implement Cache Service Abstraction**

Create reusable cache service interface and Redis implementation:

```csharp
// Services/ICacheService.cs
using System;
using System.Threading.Tasks;

namespace Gainwell.Caching.Services
{
    /// <summary>
    /// Abstraction for caching operations supporting multiple backends
    /// </summary>
    public interface ICacheService
    {
        Task<T> GetAsync<T>(string key) where T : class;
        Task<bool> SetAsync<T>(string key, T value, TimeSpan? expiration = null) where T : class;
        Task<bool> DeleteAsync(string key);
        Task<bool> ExistsAsync(string key);
        Task<long> DeleteByPatternAsync(string pattern);
        Task<bool> SetWithTagsAsync<T>(string key, T value, string[] tags, TimeSpan? expiration = null) where T : class;
    }
}

// Services/RedisCacheService.cs
using StackExchange.Redis;
using System;
using System.Text.Json;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace Gainwell.Caching.Services
{
    public class RedisCacheService : ICacheService
    {
        private readonly IConnectionMultiplexer _redis;
        private readonly ILogger<RedisCacheService> _logger;
        private readonly JsonSerializerOptions _jsonOptions;

        public RedisCacheService(
            IConnectionMultiplexer redis,
            ILogger<RedisCacheService> logger)
        {
            _redis = redis;
            _logger = logger;
            _jsonOptions = new JsonSerializerOptions
            {
                PropertyNameCaseInsensitive = true,
                WriteIndented = false
            };
        }

        public async Task<T> GetAsync<T>(string key) where T : class
        {
            try
            {
                var db = _redis.GetDatabase();
                var value = await db.StringGetAsync(key);

                if (value.IsNullOrEmpty)
                {
                    _logger.LogDebug("Cache miss for key: {CacheKey}", key);
                    return null;
                }

                _logger.LogDebug("Cache hit for key: {CacheKey}", key);
                return JsonSerializer.Deserialize<T>(value, _jsonOptions);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error getting cache key: {CacheKey}", key);
                return null; // Fail gracefully, don't throw
            }
        }

        public async Task<bool> SetAsync<T>(string key, T value, TimeSpan? expiration = null) where T : class
        {
            try
            {
                var db = _redis.GetDatabase();
                var serializedValue = JsonSerializer.Serialize(value, _jsonOptions);

                var success = await db.StringSetAsync(
                    key,
                    serializedValue,
                    expiration ?? TimeSpan.FromHours(1));

                if (success)
                {
                    _logger.LogDebug(
                        "Cache set for key: {CacheKey}, TTL: {TTL}",
                        key, expiration);
                }

                return success;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error setting cache key: {CacheKey}", key);
                return false; // Fail gracefully
            }
        }

        public async Task<bool> DeleteAsync(string key)
        {
            try
            {
                var db = _redis.GetDatabase();
                var success = await db.KeyDeleteAsync(key);

                _logger.LogDebug("Cache delete for key: {CacheKey}, Success: {Success}", key, success);
                return success;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error deleting cache key: {CacheKey}", key);
                return false;
            }
        }

        public async Task<bool> ExistsAsync(string key)
        {
            try
            {
                var db = _redis.GetDatabase();
                return await db.KeyExistsAsync(key);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error checking cache key existence: {CacheKey}", key);
                return false;
            }
        }

        public async Task<long> DeleteByPatternAsync(string pattern)
        {
            try
            {
                var endpoints = _redis.GetEndPoints();
                var server = _redis.GetServer(endpoints[0]);
                var db = _redis.GetDatabase();

                var keys = server.Keys(pattern: pattern);
                long deletedCount = 0;

                foreach (var key in keys)
                {
                    if (await db.KeyDeleteAsync(key))
                    {
                        deletedCount++;
                    }
                }

                _logger.LogInformation(
                    "Deleted {Count} keys matching pattern: {Pattern}",
                    deletedCount, pattern);

                return deletedCount;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error deleting keys by pattern: {Pattern}", pattern);
                return 0;
            }
        }

        public async Task<bool> SetWithTagsAsync<T>(string key, T value,
            string[] tags, TimeSpan? expiration = null) where T : class
        {
            try
            {
                var db = _redis.GetDatabase();
                var serializedValue = JsonSerializer.Serialize(value, _jsonOptions);

                // Set main value
                await db.StringSetAsync(key, serializedValue, expiration ?? TimeSpan.FromHours(1));

                // Add key to tag sets for tag-based invalidation
                foreach (var tag in tags)
                {
                    await db.SetAddAsync($"tag:{tag}", key);
                }

                return true;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error setting cache with tags for key: {CacheKey}", key);
                return false;
            }
        }
    }
}
```

**Step 2.2: Implement Cache-Aside Pattern in Repository**

```csharp
// Repositories/ProviderRepository.cs
using Gainwell.Caching.Services;
using Gainwell.Domain.Models;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using System;
using System.Threading.Tasks;

namespace Gainwell.Providers.Repositories
{
    public class ProviderRepository : IProviderRepository
    {
        private readonly ApplicationDbContext _context;
        private readonly ICacheService _cache;
        private readonly ILogger<ProviderRepository> _logger;
        private const int CacheTTLHours = 1;

        public ProviderRepository(
            ApplicationDbContext context,
            ICacheService cache,
            ILogger<ProviderRepository> logger)
        {
            _context = context;
            _cache = cache;
            _logger = logger;
        }

        public async Task<Provider> GetByNpiAsync(string tenantId, string npi)
        {
            // Generate cache key with tenant isolation
            var cacheKey = $"{tenantId}:provider:npi:{npi}";

            // Check cache first (cache-aside pattern)
            var cachedProvider = await _cache.GetAsync<Provider>(cacheKey);
            if (cachedProvider != null)
            {
                _logger.LogDebug(
                    "Provider {NPI} retrieved from cache for tenant {TenantId}",
                    npi, tenantId);
                return cachedProvider;
            }

            // Cache miss - query database
            _logger.LogDebug(
                "Cache miss for provider {NPI}, querying database", npi);

            var provider = await _context.Providers
                .AsNoTracking()
                .FirstOrDefaultAsync(p => p.TenantId == tenantId && p.NPI == npi);

            if (provider != null)
            {
                // Populate cache for future requests
                await _cache.SetAsync(
                    cacheKey,
                    provider,
                    TimeSpan.FromHours(CacheTTLHours));

                _logger.LogDebug(
                    "Provider {NPI} cached with TTL {TTL} hours",
                    npi, CacheTTLHours);
            }

            return provider;
        }

        public async Task<Provider> UpdateProviderAsync(Provider provider)
        {
            // Update database
            _context.Providers.Update(provider);
            await _context.SaveChangesAsync();

            // Invalidate cache (cache-aside pattern)
            var cacheKey = $"{provider.TenantId}:provider:npi:{provider.NPI}";
            await _cache.DeleteAsync(cacheKey);

            // Invalidate related caches (provider searches, directory listings)
            await _cache.DeleteByPatternAsync($"{provider.TenantId}:provider:search:*");

            _logger.LogInformation(
                "Provider {NPI} updated and cache invalidated",
                provider.NPI);

            return provider;
        }
    }
}
```

**Step 2.3: Implement HTTP Cache Headers for Client-Side Caching**

```csharp
// Middleware/CacheHeaderMiddleware.cs
using Microsoft.AspNetCore.Http;
using System;
using System.Threading.Tasks;

namespace Gainwell.API.Middleware
{
    public class CacheHeaderMiddleware
    {
        private readonly RequestDelegate _next;

        public CacheHeaderMiddleware(RequestDelegate next)
        {
            _next = next;
        }

        public async Task InvokeAsync(HttpContext context)
        {
            // Set cache headers based on endpoint type
            var path = context.Request.Path.Value;

            if (path.StartsWith("/api/reference/"))
            {
                // Reference data (diagnosis codes, etc.) - cache for 24 hours
                context.Response.Headers.CacheControl = "public, max-age=86400";
                context.Response.Headers.Vary = "Accept-Encoding";
            }
            else if (path.StartsWith("/api/providers/directory"))
            {
                // Provider directory - cache for 1 hour
                context.Response.Headers.CacheControl = "public, max-age=3600";
                context.Response.Headers.Vary = "Accept-Encoding";
            }
            else if (path.StartsWith("/api/members/") && context.Request.Method == "GET")
            {
                // Member data - private cache only, 5 minutes
                context.Response.Headers.CacheControl = "private, max-age=300";
            }
            else
            {
                // Default - no cache
                context.Response.Headers.CacheControl = "no-cache, no-store, must-revalidate";
            }

            await _next(context);

            // Add ETag for conditional requests
            if (context.Response.StatusCode == 200 &&
                context.Request.Method == "GET" &&
                !string.IsNullOrEmpty(context.Response.ContentType))
            {
                // Generate ETag from Last-Modified or content hash
                var etag = GenerateETag(context);
                if (!string.IsNullOrEmpty(etag))
                {
                    context.Response.Headers.ETag = etag;
                }
            }
        }

        private string GenerateETag(HttpContext context)
        {
            // Simplified ETag generation - in production use content hash
            var lastModified = DateTime.UtcNow.ToString("O");
            return $"\"{Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(lastModified))}\"";
        }
    }
}
```

**Step 2.4: Configure DI Container and Startup**

```csharp
// Program.cs
using StackExchange.Redis;
using Gainwell.Caching.Services;

var builder = WebApplication.CreateBuilder(args);

// Configure Redis connection
var redisConnection = builder.Configuration.GetValue<string>("Redis:ConnectionString");
builder.Services.AddSingleton<IConnectionMultiplexer>(
    ConnectionMultiplexer.Connect(redisConnection));

// Register cache service
builder.Services.AddSingleton<ICacheService, RedisCacheService>();

// Add memory cache for local caching
builder.Services.AddMemoryCache();

// Configure distributed caching
builder.Services.AddStackExchangeRedisCache(options =>
{
    options.Configuration = redisConnection;
    options.InstanceName = "Gainwell:";
});

var app = builder.Build();

// Add cache header middleware
app.UseMiddleware<CacheHeaderMiddleware>();

app.Run();
```

