#### Phase 3: Advanced Features (Week 4-5)

**Step 3.1: Implement Cache Warming on Startup**

```csharp
// Services/CacheWarmingService.cs
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using System;
using System.Threading;
using System.Threading.Tasks;

namespace Gainwell.Caching.Services
{
    public class CacheWarmingService : IHostedService
    {
        private readonly ICacheService _cache;
        private readonly IServiceProvider _serviceProvider;
        private readonly ILogger<CacheWarmingService> _logger;

        public CacheWarmingService(
            ICacheService cache,
            IServiceProvider serviceProvider,
            ILogger<CacheWarmingService> logger)
        {
            _cache = cache;
            _serviceProvider = serviceProvider;
            _logger = logger;
        }

        public async Task StartAsync(CancellationToken cancellationToken)
        {
            _logger.LogInformation("Starting cache warming...");

            try
            {
                // Warm reference data caches
                await WarmReferenceDataCacheAsync();

                // Warm frequently accessed provider data
                await WarmProviderCacheAsync();

                _logger.LogInformation("Cache warming completed successfully");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error during cache warming");
            }
        }

        public Task StopAsync(CancellationToken cancellationToken)
        {
            return Task.CompletedTask;
        }

        private async Task WarmReferenceDataCacheAsync()
        {
            using var scope = _serviceProvider.CreateScope();
            var context = scope.ServiceProvider
                .GetRequiredService<ApplicationDbContext>();

            // Load all diagnosis codes (finite dataset)
            var diagnosisCodes = await context.DiagnosisCodes
                .AsNoTracking()
                .ToListAsync();

            foreach (var code in diagnosisCodes)
            {
                var cacheKey = $"reference:diagnosis:{code.Code}";
                await _cache.SetAsync(
                    cacheKey,
                    code,
                    TimeSpan.FromHours(24));
            }

            _logger.LogInformation(
                "Warmed {Count} diagnosis codes",
                diagnosisCodes.Count);
        }

        private async Task WarmProviderCacheAsync()
        {
            using var scope = _serviceProvider.CreateScope();
            var context = scope.ServiceProvider
                .GetRequiredService<ApplicationDbContext>();

            // Load top 1000 most accessed providers
            var topProviders = await context.Providers
                .AsNoTracking()
                .OrderByDescending(p => p.AccessCount)
                .Take(1000)
                .ToListAsync();

            foreach (var provider in topProviders)
            {
                var cacheKey = $"{provider.TenantId}:provider:npi:{provider.NPI}";
                await _cache.SetAsync(
                    cacheKey,
                    provider,
                    TimeSpan.FromHours(1));
            }

            _logger.LogInformation(
                "Warmed {Count} top providers",
                topProviders.Count);
        }
    }
}
```

